// Get the user's question
const userMessage = $input.first().json.message.text;
const chatId = $input.first().json.message.chat.id;

// Simple RAG: Search for relevant articles
function searchKnowledgeBase(query) {
  const queryLower = query.toLowerCase();
  const results = [];

  // Keywords mapping
  const keywords = {
    'speed': ['328', 'sürət'],
    'sürət': ['328'],
    'fast': ['328'],
    'alcohol': ['333', '334'],
    'alkoqol': ['333', '334'],
    'drunk': ['333', '334'],
    'içki': ['333', '334'],
    'sərxoş': ['333', '334'],
    'license': ['332', '334'],
    'lisenziya': ['332', '334'],
    'vəsiqə': ['332'],
    'seatbelt': ['329'],
    'kəmər': ['329'],
    'helmet': ['329'],
    'dəbilqə': ['329'],
    'parking': ['346', '346-1'],
    'parklanma': ['346-1'],
    'dayanma': ['346'],
    'stop': ['346'],
    'pedestrian': ['330', '338'],
    'piyada': ['330', '338'],
    'red light': ['327'],
    'qırmızı işıq': ['327'],
    'svetofor': ['327'],
    'traffic light': ['327'],
    'insurance': ['469'],
    'sığorta': ['469'],
    'phone': ['327'],
    'telefon': ['327'],
    'emergency': ['331'],
    'təcili': ['331'],
    'ambulance': ['331'],
    'test': ['343'],
    'müayinə': ['343'],
    'exhaust': ['342'],
    'səs': ['342'],
    'loud': ['342'],
    'racing': ['511'],
    'yarış': ['511'],
    'wheelie': ['511'],
    'hooligan': ['511'],
    'xuliqan': ['511']
  };

  // Find matching article IDs
  const matchedIds = new Set();
  for (const [keyword, ids] of Object.entries(keywords)) {
    if (queryLower.includes(keyword)) {
      ids.forEach(id => matchedIds.add(id));
    }
  }

  // If no keyword match, search in article content
  if (matchedIds.size === 0) {
    for (const article of knowledgeBase.articles) {
      const articleText = JSON.stringify(article).toLowerCase();
      if (articleText.includes(queryLower) || 
          queryLower.split(' ').some(word => word.length > 3 && articleText.includes(word))) {
        matchedIds.add(article.id);
      }
    }
  }

  // Get matched articles
  for (const article of knowledgeBase.articles) {
    if (matchedIds.has(article.id)) {
      results.push(article);
    }
  }

  // If still no results, return top 3 most common violations
  if (results.length === 0) {
    results.push(
      knowledgeBase.articles.find(a => a.id === '328'), // Speeding
      knowledgeBase.articles.find(a => a.id === '346'), // Stopping
      knowledgeBase.articles.find(a => a.id === '329')  // Safety
    );
  }

  return results.slice(0, 3); // Max 3 articles for context
}

const relevantArticles = searchKnowledgeBase(userMessage);

// Format context for LLM
let context = "RELEVANT TRAFFIC FINE INFORMATION:\n\n";
for (const article of relevantArticles) {
  context += `## ${article.title}\n`;
  for (const item of article.content) {
    context += `- ${item.violation}: ${item.fine} AZN`;
    if (item.points && item.points !== 0) {
      context += `, ${item.points} points`;
    }
    context += "\n";
  }
  context += "\n";
}

return {
  json: {
    userMessage,
    chatId,
    context,
    relevantArticles
  }
};
